Definition PRIVSIG_STACK : Z := 80.

Definition privsig_post (ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (C clk lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (C, C + 48)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ APCond m' C clk
    /\ ACanaryReads m'.

Definition privsig_stmt_at (pc : Z) (STK : Z) : Prop :=
  forall (C clk lo : Z) ra sp gp tp t0 t1 t2 s0 s1 (n : word) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  APCond m C clk ->
  (C + 48 <= 0x10000 \/ 0x684000 <= C) ->
  bv_unsigned n <> 0 ->
  ACanaryReads m ->
  stk bsegs m lo (bv_unsigned sp) -> lo + STK <= bv_unsigned sp -> aceil <= lo ->
  (C + 48 <= lo \/ bv_unsigned sp <= C) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  evt bsegs (privsig_post ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc C clk lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) n a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom bsegs)).

Definition privsig_stmt : Prop := privsig_stmt_at P_A_PRIVATE_COND_SIGNAL PRIVSIG_STACK.

Lemma privsig_spec : privsig_stmt.
Proof.
  unfold privsig_stmt, privsig_stmt_at, PRIVSIG_STACK, P_A_PRIVATE_COND_SIGNAL.
  intros C clk lo ra sp gp tp t0 t1 t2 s0 s1 n a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m
    PC CRG NZ CRD ST LO CE DJ RA MI.
  try hcb. pose proof aceil_facts as ACF.
  destruct (PCond_cells _ _ _ PC) as (CC & CK & AL). clear PC.
  destruct (ACanaryReads_cells m CRD) as (can & CANR & G1 & G2). clear CRD.
  pose proof (rw_cells_bound _ _ _ _ CC) as CBD. cbn [cells_size csize Nat.add] in CBD.
  pose proof (amo_aligned_C32 C ltac:(lia) ltac:(lia) AL) as AMO.
  pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. change (2 ^ Z.of_N 64) with (2^64) in SPR.
  pose proof (munch_refl [(lo, bv_unsigned sp); (C, C + 48)]%Z m) as MU.
  pose proof (wmono_refl bsegs m) as WM.
  unfold wz, AG_GOT_STACK_CHK, AG_STACK_CHK_GUARD in *.
  carve_frame 80%nat ST.
  (* prologue: addi sp, sp, -80 and seven saves *)
  do 8 st1.
  (* mv s1, a0; mv a0, zero; auipc; ld s4 (the guard's GOT slot); ld a2, 0(s4) (the guard);
     addi s0, s1, 32 (the lock); sd a2, 16(sp); sw zero, 12(sp); li a2, 1 *)
  do 9 st1.
  (* lr.w.aqrl a3, (s0): the lock, 0 *)
  amo_step AMO.
  (* bne a3, a0: not taken *)
  st1. try first [if_false | if_true].
  (* sc.w.aqrl a4, a2, (s0): the reservation is the lr's, so the store of 1 succeeds *)
  amo_step AMO.
  (* bnez a4: not taken; sext.w a3, a3; mv s2, a1; beqz a3: taken (lock was free) *)
  st1. try first [if_false | if_true].
  st1. st1.
  st1. try first [if_true | if_false].
  (* mv s3, zero; ld a0, 40(s1) (the tail, 0); snez a4, a0 *)
  do 3 st1.
  (* beqz s2: not taken (n <> 0); beqz a0: taken (no waiters); beqz a4: taken *)
  st1. try first [if_false | if_true].
  st1. try first [if_true | if_false].
  st1. try first [if_true | if_false].
  (* sd zero, 8(s1); mv a1, zero; sd a0, 40(s1); lw a0, 0(s0) (the lock, 1) *)
  do 4 st1.
  (* lr.w.aqrl a2, (s0); bne a2, a0: not taken *)
  amo_step AMO.
  st1. try first [if_false | if_true].
  (* sc.w.aqrl a3, a1, (s0): the reservation is the lr's, so the store of 0 succeeds *)
  amo_step AMO.
  (* bnez a3: not taken; sext.w a2, a2; bne a2, a0: not taken; li a1, 2; bne a0, a1: taken (no waiter to wake) *)
  st1. try first [if_false | if_true].
  st1.
  st1. try first [if_false | if_true].
  st1.
  st1. try first [if_true | if_false].
  (* lw a2, 12(sp): ref, 0; bnez a2: not taken; beqz s3: taken *)
  st1.
  st1. try first [if_false | if_true].
  st1. try first [if_true | if_false].
  (* the canary check: ld a0, 0(s4); ld a1, 16(sp); bne a0, a1: not taken *)
  st1. st1.
  st1. try first [if_false | if_true].
  (* mv a0, zero; seven restores *)
  do 8 st1.
  release_frame FR ST (bv_unsigned sp).
  (* addi sp, sp, 80; ret *)
  st1. st1.
  finish.
  - eapply PCond_fold_sig; [ | exact CK | exact AL].
    eapply rw_cells_recells; [exact CC | cbn; repeat (first [exact I | reflexivity | split]) | reflexivity | reflexivity].
  - exact (ACanaryCells_reads _ can (conj G1 G2)).
Qed.

