Definition CV_NOTIFY_ALL_STACK : Z := 96.
Definition CV_DTOR_STACK : Z := 16.

Definition cv_notify_all_post (ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (C clk lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 a3 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (C, C + 48)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ APCond m' C clk
    /\ ACanaryReads m'
    /\ a0 = wz 0.

Definition cv_notify_all_stmt : Prop :=
  forall (C clk lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  APCond m C clk ->
  (C + 48 <= 0x10000 \/ 0x684000 <= C) ->
  ACanaryReads m ->
  stk bsegs m lo (bv_unsigned sp) -> lo + CV_NOTIFY_ALL_STACK <= bv_unsigned sp -> aceil <= lo ->
  (C + 48 <= lo \/ bv_unsigned sp <= C) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  evt bsegs (cv_notify_all_post ra sp gp tp s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc C clk lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_CV_NOTIFY_ALL) fc None m (seg_rom bsegs)).

